package com.yuegang.zhihui.knowledge.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.knowledge.application.*;import com.yuegang.zhihui.knowledge.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;@RestController @RequestMapping("/api/v1/knowledge/documents")public final class KnowledgeController{private final KnowledgeDocumentService service;private final KnowledgeUserResolver users;public KnowledgeController(KnowledgeDocumentService s,KnowledgeUserResolver u){service=s;users=u;}@PostMapping(consumes="multipart/form-data")ApiResponse<KnowledgeDocumentView>upload(@RequestParam String title,@RequestParam String category,@RequestPart MultipartFile file,HttpServletRequest r){return ok(service.upload(users.resolve(r,true),title,category,file),r);}@PostMapping("/{id}/review")ApiResponse<KnowledgeDocumentView>review(@PathVariable String id,@Valid @RequestBody ReviewKnowledgeRequest body,HttpServletRequest r){return ok(service.review(users.resolve(r,true),id,body),r);}@GetMapping("/{id}")ApiResponse<KnowledgeDocumentView>get(@PathVariable String id,HttpServletRequest r){users.resolve(r,false);return ok(service.get(Long.parseLong(id)),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,TraceIdResolver.resolve(r));}}
